"""Self-contained, offline report. No model, remote assets or scripts."""
import hashlib
import html
from pathlib import Path

NAMES = {'albumin':'Albumin','creatinine':'Creatinine','glucose':'Glucose','crp':'C-reactive protein (CRP)',
         'lymphocyte_pct':'Lymphocytes','mcv':'Mean corpuscular volume (MCV)',
         'rdw':'Red cell distribution width (RDW)','alp':'Alkaline phosphatase (ALP)','wbc':'White blood cells (WBC)'}
CSS = '''
:root{color-scheme:light;--ink:#1c2c38;--muted:#536672;--accent:#087f73;--line:#d8e5e5;--soft:#f2f8f7}
*{box-sizing:border-box}body{margin:0;background:#fff;color:var(--ink);font:16px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1120px;margin:auto;padding:40px 40px 56px}header{display:flex;align-items:center;justify-content:space-between;gap:24px;border-bottom:2px solid var(--accent);padding-bottom:22px}.brand{display:flex;align-items:center;gap:20px}.brand strong{font-size:40px;letter-spacing:-2px;line-height:1}.brand span{border-left:1px solid var(--line);padding-left:20px;font-size:18px}.local{color:var(--accent);font-size:14px;font-weight:600}.notice{padding:18px 0;color:var(--muted)}.notice strong{color:var(--accent)}h1{font-size:clamp(32px,4vw,50px);letter-spacing:-1.8px;line-height:1.15;margin:20px 0 14px}h2{font-size:22px;line-height:1.3;margin:0 0 12px;letter-spacing:-.4px}p{margin:0 0 16px}.meta{color:var(--muted);font-size:14px;margin-bottom:28px}.snapshot{border:1px solid #a4c5c2;border-radius:16px;padding:28px 32px}.ages{display:grid;grid-template-columns:1fr 1fr;gap:32px}.primary{border-right:1px solid var(--line);padding-right:24px}.label{font-size:16px;font-weight:600}.number{font-size:clamp(68px,9vw,108px);letter-spacing:-5px;line-height:1.15;color:var(--accent);font-weight:650;font-variant-numeric:tabular-nums}.unit{font-size:23px;color:var(--muted);letter-spacing:0;font-weight:400}.chrono{font-size:48px;line-height:1.3;letter-spacing:-2px;font-weight:600}.difference{font-size:24px;color:var(--accent);font-weight:600;margin:8px 0}.interpretation{border-top:1px solid var(--line);margin-top:24px;padding-top:20px;font-size:15px}.interpretation p{margin:0}.muted{color:var(--muted)}.lower{display:grid;grid-template-columns:1.35fr 1fr;gap:40px;margin:36px 0}.about{border-left:1px solid var(--line);padding-left:32px}.about p{font-size:15px;color:var(--muted)}table{border-collapse:collapse;width:100%;font-size:14px}caption{text-align:left;color:var(--muted);padding:0 0 14px}th{text-align:left;background:var(--soft);font-size:12px;text-transform:uppercase;letter-spacing:.6px}th,td{padding:10px 12px;border-bottom:1px solid var(--line)}td:nth-child(2){font-variant-numeric:tabular-nums;font-weight:600}details{border:1px solid var(--line);border-radius:12px;padding:16px 20px}summary{cursor:pointer;font-weight:600;color:var(--accent)}summary:focus-visible{outline:2px solid var(--accent);outline-offset:5px}.details{padding-top:20px;font-size:13px}.details code{overflow-wrap:anywhere;display:block;color:var(--muted)}footer{margin-top:24px;font-size:12px;color:var(--muted)}
@media(max-width:650px){main{padding:24px 20px}header{align-items:flex-start}.brand{display:block}.brand span{display:block;border:0;padding:8px 0 0;font-size:13px}.local{font-size:12px}.snapshot{padding:22px}.ages,.lower{grid-template-columns:1fr;gap:24px}.primary{border-right:0;border-bottom:1px solid var(--line);padding:0 0 20px}.about{border-left:0;border-top:1px solid var(--line);padding:24px 0 0}h1{letter-spacing:-1px}th,td{padding:9px 6px;font-size:12px}.number{font-size:80px}}
@media print{main{padding:0}.snapshot,details{break-inside:avoid}details .details{display:block}footer{font-size:10px}}
'''

def render(result, units):
    e=lambda value:html.escape(str(value),quote=True)
    demo_path=Path(__file__).resolve().parents[1]/'data/demo.csv'
    demo=(result['person_id']=='alex-demo' and result['birth_year']==1981 and
          result['source_sha256']==hashlib.sha256(demo_path.read_bytes()).hexdigest())
    notice=('<strong>Fictional demo</strong> — Alex Demo. These are sample values, not your health data.' if demo else
            '<strong>Personal research report</strong> — contains sensitive health information.')
    delta=result['delta']; direction='lower' if delta<0 else 'higher' if delta>0 else 'equal'
    difference=f'{abs(delta):.1f} years {direction}' if direction!='equal' else 'Same estimated age'
    rows=''.join(f'<tr><td>{e(NAMES.get(m,m))}</td><td>{e(format(result["values"][m],"g"))}</td><td>{e(units[m])}</td></tr>' for m in units)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><title>Hebe Longevity Intelligence · Report</title><style>{CSS}</style></head><body><main>
<header><div class="brand"><strong>Hebe</strong><span>Longevity Intelligence</span></div><span class="local">Local report</span></header>
<div class="notice">{notice}</div><h1>Your blood age snapshot.</h1>
<p class="meta">{e(result['person_id'])} · Collected {e(result['measured_at'])} · Draw {e(result['draw_id'])}</p>
<section class="snapshot" aria-label="Age comparison"><div class="ages"><div class="primary"><div class="label">Blood PhenoAge</div><div class="number">{result['pheno_age']:.1f} <span class="unit">years</span></div></div><div><div class="label">Chronological age (approx.)</div><div class="chrono">{result['chrono_age']:.1f} <span class="unit">years</span></div><div class="difference">{difference}</div><div class="muted">Compared with chronological age at collection</div></div></div>
<div class="interpretation"><p><strong>A blood-marker estimate, not a diagnosis or a direct measurement of biological age.</strong></p><p class="muted">One blood draw is shown. This report does not establish a trend or predict lifespan.</p></div></section>
<div class="lower"><section><h2>Input markers</h2><table><caption>Nine confirmed values, in the units used for calculation</caption><thead><tr><th scope="col">Marker</th><th scope="col">Value</th><th scope="col">Unit</th></tr></thead><tbody>{rows}</tbody></table></section>
<aside class="about"><h2>About this result</h2><p>The number is calculated by code from the confirmed blood markers and birth year. It is not an estimate generated by an AI model.</p><p>Chronological age uses a mid-year birth-date approximation. The difference is a comparison of two estimates, not years of life gained.</p><h2>What comes next?</h2><p>Keep the original lab report. Discuss health questions with a qualified clinician. Trends and checked research plans are not available in this version.</p><h2>Privacy</h2><p>This report uses no external scripts, fonts or network requests. Hermes may send chat and tool outputs to your configured cloud model.</p></aside></div>
<details><summary>Calculation details &amp; provenance</summary><div class="details"><p>Research and education only. Not a diagnosis or treatment recommendation. No clinical validation is claimed.</p><p>Input SHA-256<code>{e(result['source_sha256'])}</code></p><p>PLSI source commit<code>{e(result['plsi_commit'])}</code></p><p>Confirmed result<code>{e(result['id'])}</code></p></div></details>
<footer>Built on PLSI by Insilico Medicine (MIT). Not affiliated with or endorsed by Insilico Medicine or xAI.<br>Research and education only · No diagnosis or treatment recommendation</footer>
</main></body></html>'''
